package practice;

import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.DoubleConsumer;

/**
 * Pushes price ticks to the widgets of a trading screen. Each widget subscribes to one symbol
 * when it opens and closes its subscription when the trader closes it.
 */
public class PriceFeed {

    /** Ends one subscription. */
    public interface Subscription extends AutoCloseable {
        @Override
        void close();
    }

    /** One registration: which symbol, and whom to tell. */
    static final class Entry {
        final String symbol;
        final DoubleConsumer listener;

        Entry(String symbol, DoubleConsumer listener) {
            this.symbol = symbol;
            this.listener = listener;
        }
    }

    private final List<Entry> entries = new CopyOnWriteArrayList<>();

    /** Tells {@code listener} every price of {@code symbol} from now until the subscription is closed. */
    public Subscription subscribe(String symbol, DoubleConsumer listener) {
        Entry entry = new Entry(symbol, listener);
        entries.add(entry);
        return () -> entries.remove(entry);
    }

    public void tick(String symbol, double price) {
        for (Entry e : entries) {
            if (e.symbol.equals(symbol)) e.listener.accept(price);
        }
    }

    public int subscriptionCount() {
        return entries.size();
    }
}

package practice;

import java.util.ArrayList;
import java.util.List;
import java.util.function.DoubleConsumer;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            PriceFeed feed = new PriceFeed();
            List<String> heard = new ArrayList<>();
            DoubleConsumer blotter = price -> heard.add("blotter " + price);
            PriceFeed.Subscription blotterVolt = feed.subscribe("VOLT", blotter);
            feed.subscribe("ZINC", blotter);
            PriceFeed.Subscription chart = feed.subscribe("VOLT", price -> heard.add("chart " + price));
            feed.tick("VOLT", 18.4);
            blotterVolt.close();
            chart.close();
            chart.close();
            feed.subscribe("VOLT", price -> heard.add("ticker " + price));
            feed.tick("VOLT", 18.6);
            feed.tick("ZINC", 2.95);
            for (String line : heard) System.out.println("heard: " + line);
            System.out.println("subscriptions left: " + feed.subscriptionCount());
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }
}

